import{Alert,StyleSheet,Text,View}from'@/platform/react-native';import{useLocalSearchParams}from'@/router';import{useMutation,useQuery,useQueryClient}from'@tanstack/react-query';import{api}from'@/lib/api';import{Badge,Button,Card,EmptyState,Header,Muted,Screen,useAppTheme}from'@/components/UI';
export default function Moderation(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const q=useQuery<any[]>({queryKey:['moderation',id],queryFn:async()=>(await api.get(`/communities/${id}/moderation-queue`)).data,retry:false});const review=useMutation({mutationFn:({itemId,decision}:{itemId:string,decision:string})=>api.patch(`/moderation-queue/${itemId}/review`,{decision}),onSuccess:()=>qc.invalidateQueries({queryKey:['moderation',id]})});return <Screen scroll><Header title="Moderation Queue" subtitle="AI can flag content; a human administrator makes the decision"/>{!q.data?.length?<EmptyState title="Queue clear" body="No content is currently waiting for moderator review."/>:q.data.map(x=><Card key={x.Id}><View style={s.top}><Text style={[s.title,{color:palette.text}]}>{x.EntityType} · {x.ReasonCode}</Text><Badge text={x.Status}/></View><Muted>{x.Explanation||'Potentially problematic content was flagged for review.'}</Muted>{x.Confidence!=null?<Muted>Confidence: {Math.round(Number(x.Confidence)*100)}%</Muted>:null}{x.Status==='PENDING_REVIEW'?<View style={s.actions}><Button title="Approve" variant="success" onPress={()=>review.mutate({itemId:x.Id,decision:'APPROVE'})}/><Button title="Remove" variant="danger" onPress={()=>Alert.alert('Remove content?','The flagged item will be removed after your review.',[{text:'Cancel',style:'cancel'},{text:'Remove',style:'destructive',onPress:()=>review.mutate({itemId:x.Id,decision:'REMOVE'})}])}/></View>:null}</Card>)}</Screen>};const s=StyleSheet.create({top:{flexDirection:'row',justifyContent:'space-between',gap:8},title:{fontWeight:'900'},actions:{flexDirection:'row',gap:10,marginTop:8}})
